using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Linq;using System.Text;using System.Windows.Forms;
namespace BeamScheduleFormatter {
/* Staircase design sheet window: inputs (stair type and geometry, loads, materials and bars, checks), the interactive Model page
   (section, plan, 3D model, load / shear / moment diagrams; every input change redraws), Results (pass / fail, bars) and the report */
class StaircaseForm:DesignSheetForm {
 static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
 readonly StairSectionView section=new StairSectionView();readonly StairPlanView plan=new StairPlanView();readonly Stair3DView model=new Stair3DView();readonly StairDiagramView diagram=new StairDiagramView();
 readonly ComboBox member=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=320};
 readonly Label verdict=new Label{Dock=DockStyle.Top,Height=46,Font=new Font("Segoe UI Semibold",11.5f),TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(14,0,0,0),BackColor=Color.White,UseMnemonic=false,Text="Enter the stair inputs."};
 readonly DataGridView checks=Grid(),steel=Grid();readonly Timer settle=new Timer{Interval=200};
 static DataGridView Grid(){var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize};g.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;g.DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;GridAppearance.Apply(g);return g;}
 public StaircaseForm():base("Staircase Design | NSCP 2015 (ACI 318-14) - every stair type, interactive model","Staircase-Design"){
  var geo=Section("Stair type, geometry and model","Choose the stair type. Waist-slab, dog-legged, open-well and slabless stairs span along the flight with their landings; the others span across the flight (between walls, on stringer beams), cantilever from a wall, or are spiral. Dimensions in mm; risers per flight include the riser onto the landing.");
  var type=Choice(geo,"Type","Stair type",StairInput.Types);type.SelectedIndex=1;Choice(geo,"Support","Support of the flight (along)",new[]{"Simply supported","One end continuous","Both ends continuous"});Choice(geo,"Landing","Half landing (dog-legged)",new[]{"Landing spans with the flight","Landing on its own beams / walls"});
  /* supports on beams at their place on the landing (owner, 23 November 2026) */Choice(geo,"Supports","Supports",new[]{"Beams","Walls / simple supports"});Choice(geo,"TopBars","Top bars",new[]{"Full length","At the supports (L/4)"});NumberField(geo,"BeamB","Support beam width b (mm)","250");NumberField(geo,"BeamH","Support beam depth h (mm)","400");NumberField(geo,"LandingBeamAt","Landing beam from the flight (mm, 0 = at the landing end)","0");
  NumberField(geo,"Riser","Riser R (mm)","175");NumberField(geo,"Tread","Tread / going T (mm)","275");NumberField(geo,"Width","Stair width W (mm)","1200");NumberField(geo,"Waist","Waist / plate / step slab t (mm)","175");NumberField(geo,"LandingT","Landing thickness (mm)","150");
  NumberField(geo,"N1","Risers in flight 1","9");NumberField(geo,"N2","Risers in flight 2","9");NumberField(geo,"N3","Risers in flight 3 (open-well)","6");NumberField(geo,"BottomLanding","Landing before flight 1 (mm, 0 = none)","0");NumberField(geo,"MidLanding","Half landing depth (mm)","1300");NumberField(geo,"TopLanding","Landing after the last flight (mm, 0 = none)","0");NumberField(geo,"Gap","Gap between flights (mm)","100");
  NumberField(geo,"StringerB","Stringer beam b (mm)","250");NumberField(geo,"StringerH","Stringer beam h (mm)","450");NumberField(geo,"ColumnDia","Spiral: central column diameter (mm)","300");NumberField(geo,"OuterRadius","Spiral: outer radius (mm)","1200");NumberField(geo,"TreadsPerTurn","Spiral: treads per turn","16");
  var loads=Section("Loads","NSCP 2015 Table 205-1: stairs and exitways 4.8 kPa uniform, individual treads 1.33 kN concentrated; finishes on the treads and risers; concrete 23.6 kN/m³. Load combination U = 1.2D + 1.6L.");
  NumberField(loads,"LL","Live load (kPa)","4.8");NumberField(loads,"Point","Concentrated tread load (kN)","1.33");NumberField(loads,"Finish","Finishes (kPa)","1.1");NumberField(loads,"Gamma","Concrete unit weight (kN/m³)","23.6");
  var mat=Section("Materials and bars","f'c and fy in MPa; bar diameters in mm; clear cover in mm (20 for slabs not exposed to weather, NSCP Table 420.6.1.3.1).");
  NumberField(mat,"Fc","f'c (MPa)","21");NumberField(mat,"Fy","fy main bars (MPa)","414");NumberField(mat,"Fyt","fyt stirrups / ties (MPa)","275");NumberField(mat,"Cover","Clear cover (mm)","20");NumberField(mat,"MainDia","Main bar Ø (mm)","12");NumberField(mat,"DistDia","Distribution bar Ø (mm)","10");NumberField(mat,"StringerDia","Stringer bar Ø (mm)","16");NumberField(mat,"StirrupDia","Stringer stirrup Ø (mm)","10");
  var lim=Section("Geometry limits","Limits for the geometry checks; set them to the governing code or the owner's standard (PD 1096, RA 9514 for exits).");
  NumberField(lim,"MaxRiser","Maximum riser (mm)","190");NumberField(lim,"MinTread","Minimum tread (mm)","250");NumberField(lim,"Min2RT","2R + T at least (mm)","550");NumberField(lim,"Max2RT","2R + T at most (mm)","700");NumberField(lim,"MinWidth","Minimum width (mm)","1100");NumberField(lim,"Headroom","Minimum headroom (mm)","2100");
  /* the Model page: the four interactive views */
  var page=new TabPage("Model");/* no longer its own tab */var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=40,Padding=new Padding(6)};top.Controls.Add(new Label{Text="Member / flight",AutoSize=true,Padding=new Padding(0,6,4,0)});top.Controls.Add(member);
  var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2,BackColor=Color.FromArgb(210,214,220),Padding=new Padding(1)};for(int k=0;k<2;k++){grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));grid.RowStyles.Add(new RowStyle(SizeType.Percent,50));}
  Func<string,Control,Control> framed=(t,c)=>{var p=new Panel{Dock=DockStyle.Fill,Margin=new Padding(1),BackColor=Color.White};var h=new Label{Text=t,Dock=DockStyle.Top,Height=22,Font=ModernUi.Strong,ForeColor=PowTheme.Teal,Padding=new Padding(6,3,0,0)};p.Controls.Add(c);p.Controls.Add(h);return p;};
  grid.Controls.Add(framed("SECTION WITH REINFORCEMENT",section),0,0);grid.Controls.Add(framed("3D MODEL (drag to rotate)",model),1,0);grid.Controls.Add(framed("PLAN",plan),0,1);grid.Controls.Add(framed("LOAD, SHEAR AND MOMENT (FACTORED)",diagram),1,1);
  /* one page for the stair type, geometry and model (owner, 23 November 2026: "pagsamasamahin yung stair type at yung staircase design",
     "stair type and geometry at model"): the inputs on the left, the four interactive views on the right, redrawn as the inputs change */
  page.Dispose();var modelPane=new Panel{Tag="FullWidth",Height=640,BackColor=Color.White};modelPane.Controls.Add(grid);modelPane.Controls.Add(top);geo.Controls.Add(modelPane);
  var right=(FlowLayoutPanel)geo.Tag;right.Resize+=(s0,e0)=>{int h=Math.Max(560,right.ClientSize.Height-14);if(modelPane.Height!=h)modelPane.Height=h;};
  var res=new TabPage("Results");var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal};split.Panel1.Controls.Add(checks);split.Panel2.Controls.Add(steel);res.Controls.Add(split);res.Controls.Add(verdict);AddResultPage(res);
  foreach(var h in new[]{"Check","Clause","Member","Demand","Capacity","Ratio","Status","Detail"})checks.Columns.Add(h,h.ToUpperInvariant());foreach(var h in new[]{"Member","Bars","Provide"})steel.Columns.Add(h,h.ToUpperInvariant());
  member.SelectedIndexChanged+=(s,e)=>{section.Member=member.SelectedIndex;diagram.Member=member.SelectedIndex;section.Invalidate();diagram.Invalidate();};
  foreach(var c in Inputs.Values){c.TextChanged+=(s,e)=>{if(!Restoring)Later();};var cb=c as ComboBox;if(cb!=null)cb.SelectedIndexChanged+=(s,e)=>{if(!Restoring)Later();};}
  settle.Tick+=(s,e)=>{settle.Stop();RefreshNow();};FormClosed+=(s,e)=>settle.Dispose();Shown+=(s,e)=>RefreshNow();}
 /* files saved before the support beams existed open with beams 250 x 400 at the landing end */
 protected override bool OptionalSavedInput(string key){return key=="TopBars"||key=="Supports"||key=="BeamB"||key=="BeamH"||key=="LandingBeamAt";}
 void Later(){settle.Stop();settle.Start();}
 protected override void AfterRestore(){RefreshNow();}
 internal StairInput Input(){Func<string,double> n=k=>Number(k);return new StairInput{Type=Value("Type"),Support=Value("Support"),Landing=Value("Landing"),Riser=n("Riser"),Tread=n("Tread"),Width=n("Width"),Waist=n("Waist"),LandingT=n("LandingT"),N1=(int)n("N1"),N2=(int)n("N2"),N3=(int)n("N3"),BottomLanding=n("BottomLanding"),MidLanding=n("MidLanding"),TopLanding=n("TopLanding"),Gap=n("Gap"),
  Supports=Value("Supports"),TopBars=Value("TopBars"),BeamB=n("BeamB"),BeamH=n("BeamH"),LandingBeamAt=n("LandingBeamAt"),StringerB=n("StringerB"),StringerH=n("StringerH"),ColumnDia=n("ColumnDia"),OuterRadius=n("OuterRadius"),TreadsPerTurn=n("TreadsPerTurn"),LL=n("LL"),Point=n("Point"),Finish=n("Finish"),Gamma=n("Gamma"),Fc=n("Fc"),Fy=n("Fy"),Fyt=n("Fyt"),Cover=n("Cover"),MainDia=n("MainDia"),DistDia=n("DistDia"),StringerDia=n("StringerDia"),StirrupDia=n("StirrupDia"),
  MaxRiser=n("MaxRiser"),MinTread=n("MinTread"),Min2RT=n("Min2RT"),Max2RT=n("Max2RT"),MinWidth=n("MinWidth"),Headroom=n("Headroom")};}
 void RefreshNow(){checks.Rows.Clear();steel.Rows.Clear();StairInput inp=null;StairResult r=null;try{inp=Input();r=Staircase.Design(inp);}catch(Exception ex){verdict.ForeColor=Color.Firebrick;verdict.Text=ex.Message;}
  foreach(var v in new StairZoomView[]{section,plan,model,diagram}){v.Input=inp;v.Result=r;v.Invalidate();}if(r==null)return;
  int keep=member.SelectedIndex;member.Items.Clear();foreach(var m in r.Members)member.Items.Add(m.Name);if(member.Items.Count>0)member.SelectedIndex=Math.Max(0,Math.Min(keep,member.Items.Count-1));
  foreach(var c in r.Checks){int k=checks.Rows.Add(c.Name,c.Clause,c.Member,Staircase.F(c.Demand,"0.##")+" "+c.Unit,Staircase.F(c.Capacity,"0.##")+" "+c.Unit,Staircase.F(c.Ratio,"0.00"),c.Ok?"OK":"NG",c.Detail);if(!c.Ok)checks.Rows[k].DefaultCellStyle.ForeColor=Color.Firebrick;}
  foreach(var s in r.Steel)steel.Rows.Add(s[0],s[1],s[2]);int ng=r.Checks.Count(c=>!c.Ok);verdict.ForeColor=ng>0?Color.Firebrick:Color.FromArgb(28,122,84);verdict.Text=(ng>0?"✕  "+ng+" of "+r.Checks.Count+" checks do not pass":"✓  All "+r.Checks.Count+" checks pass")+"   ·   largest ratio "+Staircase.F(r.Checks.Max(c=>c.Ratio),"0.00");}
 /* the report: design basis, geometry, loads, analysis, design checks, bars, figures of the model views */
 protected override CalculationDocument BuildDocument(){var i=Input();var r=Staircase.Design(i);Func<double,string> f2=v=>Staircase.F(v,"0.00");var rep=new RichReport("Staircase Design - "+i.Type);
  rep.Heading("1  DESIGN BASIS").Paragraph("NSCP 2015 (ACI 318-14). Loads per NSCP Table 205-1 (stairs and exitways "+Staircase.F(i.LL,"0.0#")+" kPa, treads "+Staircase.F(i.Point,"0.0#")+" kN concentrated); U = 1.2D + 1.6L (405.3.1). "+(i.Cantilever||i.Transverse||i.Stringer||i.Spiral?"The steps span across the flight; each step is designed as a rectangular section, tread wide, of the mean step depth.":"Each flight with its landings is a one-way slab spanning along the flight on plan, designed per metre width."));
  rep.Heading("2  GEOMETRY").KeyValues(new[]{new[]{"Type",i.Type},new[]{"Riser / tread",Staircase.F(i.Riser,"0")+" / "+Staircase.F(i.Tread,"0")+" mm (2R + T = "+Staircase.F(2*i.Riser+i.Tread,"0")+", slope "+Staircase.F(i.Theta*180/Math.PI,"0.0")+"°)"},new[]{"Width",Staircase.F(i.Width,"0")+" mm"},new[]{"Waist / landing",Staircase.F(i.Waist,"0")+" / "+Staircase.F(i.LandingT,"0")+" mm"},new[]{"Risers per flight",i.N1+(i.Flights>1?", "+i.N2:"")+(i.Flights>2?", "+i.N3:"")},new[]{"Support",i.Support}});
  rep.Figure(260,(g,rc)=>Paint(plan,g,rc,i,r),"Plan").Figure(260,(g,rc)=>Paint(model,g,rc,i,r),"3D model");
  rep.Heading("3  LOADS").Table(new[]{"Load","Flight (kPa on plan)","Landing (kPa)"},new[]{new[]{"Dead (self weight + finishes)",f2(r.Wd),f2(r.WdLanding)},new[]{"Live",f2(r.Wl),f2(r.WlLanding)},new[]{"Factored 1.2D + 1.6L",f2(1.2*r.Wd+1.6*r.Wl),f2(1.2*r.WdLanding+1.6*r.WlLanding)}},new[]{2f,1.2f,1.2f});
  rep.Paragraph("Flight dead load = γc (t √(R² + T²) / T + R / 2) + finishes (R + T) / T = "+Staircase.F(i.Gamma,"0.0")+" × ("+Staircase.F(i.Waist/1000,"0.000")+" × "+Staircase.F(Math.Sqrt(i.Riser*i.Riser+i.Tread*i.Tread)/i.Tread,"0.000")+" + "+Staircase.F(i.Riser/2000,"0.000")+") + "+Staircase.F(i.Finish,"0.00")+" × "+Staircase.F((i.Riser+i.Tread)/i.Tread,"0.000")+" = "+f2(r.Wd)+" kPa.");
  rep.Heading("4  ANALYSIS AND DESIGN");for(int k=0;k<r.Members.Count;k++){int kk=k;var m=r.Members[k];rep.Paragraph(m.Name+" - span "+Staircase.F(m.Length,"0.00")+" m, "+m.Support.ToLowerInvariant(),false,true);rep.Figure(250,(g,rc)=>{diagram.Member=kk;Paint(diagram,g,rc,i,r);});if(!(i.Cantilever||i.Spiral||i.Transverse||i.Stringer)||k==0)rep.Figure(380,(g,rc)=>{section.Member=kk;Paint(section,g,rc,i,r);},"Section with reinforcement");}
  /* the complete calculation of each member, step by step with the values (owner, 23 November 2026) */
  if(r.Calc.Count>0){rep.Heading("4A  DETAILED CALCULATION");foreach(var g0 in r.Calc.GroupBy(q=>q[0])){rep.Paragraph(g0.Key,false,true);rep.Table(new[]{"Step","Formula and values","Result"},g0.Select(q=>new[]{q[1],q[2],q[3]}).ToList(),new[]{1.3f,3.2f,1.6f});}}
  rep.Heading("5  CHECKS");foreach(var c in r.Checks)rep.Check(c.Name+" - "+c.Member,c.Clause,c.Detail==""?new string[0]:new[]{c.Detail},"",c.Demand,c.Capacity,c.Unit,c.Ok);
  /* the marks A / B / C of the section figures, and the section of each flight beside its bars */
  Func<string,string> mark=bars=>bars.StartsWith("Main bottom",StringComparison.OrdinalIgnoreCase)?"A":bars.StartsWith("Top bars at the supports",StringComparison.OrdinalIgnoreCase)||bars.StartsWith("Top bars over",StringComparison.OrdinalIgnoreCase)||bars.StartsWith("Top bars, full length",StringComparison.OrdinalIgnoreCase)?"B":bars.StartsWith("Distribution",StringComparison.OrdinalIgnoreCase)?"C":bars.StartsWith("Chair",StringComparison.OrdinalIgnoreCase)?"D":bars.StartsWith("Nosing",StringComparison.OrdinalIgnoreCase)?"E":"";
  bool along=!(i.Cantilever||i.Spiral||i.Transverse||i.Stringer||i.Slabless);
  rep.Heading("6  REINFORCEMENT").Table(new[]{"Mark","Member","Bars","Provide"},r.Steel.Select(q=>new[]{along?mark(q[1]):"",q[0],q[1],q[2]}).ToList(),new[]{0.5f,1.6f,2.2f,1.4f});
  if(along){rep.Paragraph("A = main bottom bars, B = top bars ("+(i.TopFull?"full length":"at the supports")+"), C = distribution bars, D = chair bars, E = nosing bars, as marked on each section below; the anchorage of A and B into the supports is drawn and dimensioned.");for(int k=0;k<r.Members.Count;k++){int kk=k;rep.Figure(380,(g,rc)=>{section.Member=kk;Paint(section,g,rc,i,r);},r.Members[k].Name+" - section with reinforcement");}}if(r.Notes.Count>0){rep.Heading("7  NOTES");foreach(var n in r.Notes)rep.Paragraph(n);}
  section.Member=Math.Max(0,member.SelectedIndex);diagram.Member=Math.Max(0,member.SelectedIndex);rep.Signatures("Prepared by","Checked by");return rep.Build();}
 /* figures are drawn at screen size (1400 px wide) and scaled into the report, so labels, callouts and bars keep the layout seen on screen
    (owner, 23 November 2026: "ayusin din sa reports, mas malaki para makita lahat ng details") */
 static void Paint(StairZoomView v,Graphics g,RectangleF rc,StairInput i,StairResult r){v.Input=i;v.Result=r;if(rc.Width<=1||rc.Height<=1)return;int w=1400,h=Math.Max(200,(int)(1400*rc.Height/rc.Width));
  using(var bmp=new Bitmap(w,h)){using(var bg=Graphics.FromImage(bmp)){bg.Clear(Color.White);bg.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;bg.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;v.RenderTo(bg,new RectangleF(0,0,w,h));}
   var st=g.Save();g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(bmp,rc);g.Restore(st);}}
 protected override string BuildReport(){var i=Input();var r=Staircase.Design(i);var b=new StringBuilder();b.AppendLine("STAIRCASE DESIGN - "+i.Type.ToUpperInvariant());b.AppendLine();b.AppendLine("## 01  CHECKS");foreach(var c in r.Checks)b.AppendLine(c.Name+" ["+c.Clause+"] "+c.Member+": "+Staircase.F(c.Demand,"0.##")+" / "+Staircase.F(c.Capacity,"0.##")+" "+c.Unit+" "+(c.Ok?"OK":"NG"));
  b.AppendLine();b.AppendLine("## 02  REINFORCEMENT");foreach(var s in r.Steel)b.AppendLine(s[0]+": "+s[1]+" - "+s[2]);return b.ToString();}
}
}
